import{z as o,x as s,o as e,c as d,q as r,j as n,D as a,d as B,s as i,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"标签工程的深化","description":"","frontmatter":{"title":"标签工程的深化","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/fml-label-engineering-deep.md","filePath":"quant/fml-label-engineering-deep.md","lastUpdated":1791063341000}'),p={name:"quant/fml-label-engineering-deep.md"};function m(h,E,C,u,_,D){const A=s("Mermaid");return e(),d("div",null,[E[2]||(E[2]=r('<h1 id="标签工程的深化" tabindex="-1">标签工程的深化 <a class="header-anchor" href="#标签工程的深化" aria-label="Permalink to &quot;标签工程的深化&quot;">​</a></h1><div class="epigraph"><p>标签定义了模型在学什么：折叠成固定期的终点收益，学的是期末；挂在退出规则上的首达标签，学的才是可执行的触发概率。</p><footer>—— 据 López de Prado, Advances in Financial Machine Learning, 2018，第 3 章；Hansen and Hodrick, JPE, 1980 整理</footer></div><p><a href="/quant/fml-feature-store-deep">上一课</a>把特征钉成带版本哈希的只读快照，\\(X\\) 侧有了契约。缺口转到 \\(y\\) 侧：多数流水线里标签仍是一段裸收益——固定预测期的折返收益，与任何退出规则都不同构。<a href="/quant/label-horizon-overlap">标签、预测期与重叠</a>已讲重叠标签的推断代价，<a href="/quant/triple-barrier">Triple Barrier 标签</a>立了首达标签的定义。本课深化标签工程本身：障碍宽度的标定、样本权重、标签形态的选择，以及标签自己的数据挖掘风险。后课的选择协议默认标签已经冻结。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>裸收益标签有四处硬伤。其一，与执行不同构：固定 \\(h\\) 的终点收益混着模型无法预测的期末噪声，而真实持仓会因止盈止损提前离场。其二，重叠：\\(h\\) 期滑动窗口让相邻样本共享路径，有效样本数远小于名义 \\(N\\)。其三，类别失衡跟着体制走：牛市里上涨类占优，分类器学会的是先验而不是信号。其四，最隐蔽：障碍宽度若用全样本校准，就是对标签本身的数据挖掘——泄漏不经过特征，直接进 \\(y\\)，任何特征侧的清洗都拦不住。</p><p><span class="marginnote">固定期终点收益标签，好比考驾照只看终点的照片：中途变道、急刹全被抹掉，而真实驾驶恰恰发生在路上。持仓常因止盈止损提前离场，裸收益标签却假设你一定拿满 \\(h\\) 天——学的和做的不是一回事。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把标签写成四元组：事件、触达规则、权重、评估口径，四项各自冻结、随模型哈希入库，与<a href="/quant/fml-feature-store-deep">上一课</a>的特征版本同账管理。障碍宽度用当时可得的波动率标定：上下障碍取 \\(k\\sigma_t\\)（\\(\\sigma_t\\) 为 EWMA 波动），时间障碍取流动性允许的最短持有期；标定 \\(k\\) 的每一次尝试都计入 \\(N\\)。权重有两层：唯一性权重按样本生命期与同时重叠的标签数分摊，\\(w_i\\propto 1/\\sum_j \\mathbb{1}\\{[t_{i,0},t_{i,1}]\\cap[t_{j,0},t_{j,1}]\\neq\\emptyset\\}\\)；收益归因权重则给「该样本独享的那段收益」更大话语权。评估口径写死：分类输出接概率校准与扣费后边缘，准确率不进验收表。</p><p><span class="marginnote">唯一性权重翻译成大白话：同一段行情被 5 个重叠样本共享，每个样本就只算五分之一份证据——像合租的水电费按人头分摊，谁也不能把同一度电重复报五次。不加权，模型就把一段行情当五段行情来学。</span></p><p><span class="marginnote">常见误区：把障碍宽度 \\(k\\) 当普通超参做网格搜索。障碍宽度决定正负样本怎么划，全样本调 \\(k\\) 是在给标签本身挑好看的分法——这条泄漏路径不经过特征，特征侧清洗再严格也拦不住，只能靠预声明加计入 \\(N\\)。</span></p>',10)),(e(),n(l,null,{default:a(()=>[i(A,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20EVT%5B%22%E4%BA%8B%E4%BB%B6%E5%AE%9A%E4%B9%89%EF%BC%9A%E4%BD%95%E6%97%B6%E5%85%A5%E5%9C%BA%22%5D%20--%3E%20BAR%5B%22%E8%A7%A6%E8%BE%BE%E8%A7%84%E5%88%99%EF%BC%9A%E4%B8%8A%E3%80%81%E4%B8%8B%E3%80%81%E6%97%B6%E9%97%B4%E9%9A%9C%E7%A2%8D%22%5D%0A%20%20BAR%20--%3E%20LAB%5B%22%E9%A6%96%E8%BE%BE%E6%A0%87%E7%AD%BE%22%5D%0A%20%20LAB%20--%3E%20W%5B%22%E5%94%AF%E4%B8%80%E6%80%A7%E4%B8%8E%E5%BD%92%E5%9B%A0%E6%9D%83%E9%87%8D%22%5D%0A%20%20W%20--%3E%20FREEZE%5B%22%E5%86%BB%E7%BB%93%E5%9B%9B%E5%85%83%E7%BB%84%E5%93%88%E5%B8%8C%22%5D%0A%20%20FREEZE%20--%3E%20EVAL%5B%22%E8%AF%84%E4%BC%B0%EF%BC%9A%E6%A0%A1%E5%87%86%E6%A6%82%E7%8E%87%E6%8E%A5%E6%89%A3%E8%B4%B9%E5%90%8E%E8%BE%B9%E7%BC%98%22%5D%0A%20%20BAR%20--%3E%7C%22'k'%20%E7%94%A8%E5%85%A8%E6%A0%B7%E6%9C%AC%E8%B0%83%E4%BC%98%22%7C%20LEAK%5B%22%E5%AF%B9%E6%A0%87%E7%AD%BE%E7%9A%84%E6%95%B0%E6%8D%AE%E6%8C%96%E6%8E%98%22%5D%0A%20%20LEAK%20--%3E%7C%E7%A6%81%E6%AD%A2%7C%20FREEZE%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t("h2",{id:"机制",tabindex:"-1"},[B("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=t("p",null,"标签决定「模型在学什么」。固定 \\(h\\) 标签下，最优预测器是条件期望 \\(\\mathbb{E}[r_{t:t+h}\\mid X_t]\\)，期末噪声全部进方差；三重障碍下，最优预测器是首达概率 \\(P(\\tau_{\\mathrm{up}}\\lt\\tau_{\\mathrm{down}},\\,\\tau_{\\mathrm{up}}\\le T\\mid X_t)\\)——退出规则从后处理搬进了目标函数，分数高才对应「这笔会按规则赢」。权重为什么必须：重叠样本不是独立证据，不加权则有效样本被同一段行情重复计数，一切 \\(t\\) 统计量虚高，下一课选择协议的全部显著性都建立在失效的地基上。\\(k\\) 全样本调优的泄漏路径：障碍决定正负样本的分布，调优会把 \\(k\\) 推向「历史更好分」的那一侧，模型于是学会了 \\(k\\) 的选择过程，而不是市场。",-1)),(e(),n(l,null,{default:a(()=>[i(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20FH%5B%22%E5%9B%BA%E5%AE%9A%20h%20%E6%A0%87%E7%AD%BE%EF%BC%9At%20%E5%88%B0%20t%2Bh%20%E7%9A%84%E6%94%B6%E7%9B%8A%22%5D%20--%3E%20CE%5B%22%E6%9C%80%E4%BC%98%E9%A2%84%E6%B5%8B%EF%BC%9A%E6%9D%A1%E4%BB%B6%E6%9C%9F%E6%9C%9B%20E%20of%20r%20given%20X%22%5D%0A%20%20CE%20--%3E%20N%5B%22%E6%9C%9F%E6%9C%AB%E5%99%AA%E5%A3%B0%E5%85%A8%E9%83%A8%E8%BF%9B%E6%96%B9%E5%B7%AE%22%5D%0A%20%20TB%5B%22%E4%B8%89%E9%87%8D%E9%9A%9C%E7%A2%8D%E6%A0%87%E7%AD%BE%EF%BC%9A%E4%B8%8A%E4%B8%8B%E9%9A%9C%E7%A2%8D%E5%8A%A0%E6%97%B6%E9%99%90%22%5D%20--%3E%20FP%5B%22%E6%9C%80%E4%BC%98%E9%A2%84%E6%B5%8B%EF%BC%9A%E9%A6%96%E8%BE%BE%E6%A6%82%E7%8E%87%20P%20%E4%B8%8A%E9%9A%9C%E5%85%88%E5%88%B0%22%5D%0A%20%20FP%20--%3E%20EX%5B%22%E9%80%80%E5%87%BA%E8%A7%84%E5%88%99%E8%BF%9B%E7%9B%AE%E6%A0%87%E5%87%BD%E6%95%B0%22%5D%0A%20%20EX%20--%3E%20W%5B%22%E5%88%86%E6%95%B0%E9%AB%98%E7%AD%89%E4%BA%8E%E8%BF%99%E7%AC%94%E4%BC%9A%E6%8C%89%E8%A7%84%E5%88%99%E8%B5%A2%22%5D%0A%20%20N%20--%3E%20Q%5B%22%E5%88%86%E6%95%B0%E4%B8%8E%E6%89%A7%E8%A1%8C%E8%84%B1%E8%8A%82%22%5D%0A%20%20W%20--%3E%20OK%5B%22%E5%88%86%E6%95%B0%E4%B8%8E%E6%89%A7%E8%A1%8C%E5%90%8C%E6%9E%84%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">以 5 日持有、样本逐日重叠为例：名义 5000 个样本的独立观测可能不足 1000，未修正的 \\(t\\) 统计量虚高约 \\(\\sqrt{5}\\approx 2.2\\) 倍；这是不加权、不清洗的默认后果，不是极端假设。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>重叠的推断修正与泄漏窗口的删除分别由<a href="/quant/label-horizon-overlap">标签、预测期与重叠</a>与<a href="/quant/purge-embargo">Purge 与 Embargo</a>承担，本课不重推。Meta-labeling 的次级标签协议已有<a href="/quant/meta-labeling">专课</a>，只引用不展开。标签形态不替你选，由执行语义决定：有离散退出规则的策略用障碍标签，只做组合权重微调的用连续或排序标签——把障碍硬套在日频再平衡上，是给不会发生的离场打分。标签随体制的分布漂移是本课程漂移管理一课的对象，此处不展开。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>标签写成四元组：事件、触达规则、权重、评估口径，冻结并与特征同账管理。</li><li>障碍宽度用当时可得的波动率标定，标定尝试计入 \\(N\\)；全样本调 \\(k\\) 是对标签的数据挖掘。</li><li>唯一性权重修正重叠计数，归因权重给独享收益话语权；不加权则显著性普遍虚高。</li><li>障碍标签把退出规则搬进目标函数，分数对应可执行的触发概率。</li><li>出处：López de Prado, <em>Advances in Financial Machine Learning</em>, Wiley, 2018，第 3 章；Hansen and Hodrick, <em>JPE</em>, 1980。</li></ul>',5))])}const b=o(p,[["render",m]]);export{c as __pageData,b as default};
